INSERT INTO `checklist_templates` VALUES (3,'survey','comprehensive','종합 진단 설문','[{\"id\": \"Q1\", \"category\": \"\\uc885\\ud569\\ub9cc\\uc871\\ub3c4\", \"text\": \"\\uc6b0\\ub9ac \\ub3d9\\ub124\\uc758 \\uc804\\ubc18\\uc801\\uc778 \\uacf5\\uacf5\\ud658\\uacbd(\\uc548\\uc804, \\ud3b8\\ub9ac\\ud568)\\uc5d0 \\ub300\\ud574 \\ub9cc\\uc871\\ud558\\uc2dc\\ub098\\uc694?\", \"type\": \"scale_5\", \"options\": [\"\\ub9e4\\uc6b0 \\ubd88\\ub9cc\\uc871\", \"\\ubd88\\ub9cc\\uc871\", \"\\ubcf4\\ud1b5\", \"\\ub9cc\\uc871\", \"\\ub9e4\\uc6b0 \\ub9cc\\uc871\"], \"subQuestions\": [{\"id\": \"Q1-1\", \"category\": \"\\uc601\\uc5ed \\ud3c9\\uac00\", \"text\": \"[\\uc8fc\\uac70] \\ud604\\uc7ac \\uac70\\uc8fc\\ud558\\uc2dc\\ub294 \\ub3d9\\ub124\\uc5d0\\uc11c **\\uc8fc\\uac70(\\ub178\\ud6c4 \\uc8fc\\ud0dd, \\uace8\\ubaa9\\uae38 \\ub4f1)**\\uc740 \\uc5bc\\ub9c8\\ub098 \\ub354 \\uac1c\\uc120\\ub420 \\ud544\\uc694\\uac00 \\uc788\\ub2e4\\uace0 \\ub290\\ub07c\\uc2ed\\ub2c8\\uae4c?\", \"type\": \"scale_5\", \"options\": [\"\\ub9e4\\uc6b0 \\ubd88\\ub9cc\\uc871\", \"\\ubd88\\ub9cc\\uc871\", \"\\ubcf4\\ud1b5\", \"\\ub9cc\\uc871\", \"\\ub9e4\\uc6b0 \\ub9cc\\uc871\"], \"subQuestions\": []}, {\"id\": \"Q1-2\", \"category\": \"\\uc601\\uc5ed \\ud3c9\\uac00\", \"text\": \"[\\ud658\\uacbd] **\\ud658\\uacbd(\\uc4f0\\ub808\\uae30, \\ubbf8\\uc138\\uba3c\\uc9c0, \\ub179\\uc9c0 \\ub4f1)**\\uc740 \\uc5bc\\ub9c8\\ub098 \\ub354 \\uac1c\\uc120\\ub420 \\ud544\\uc694\\uac00 \\uc788\\ub2e4\\uace0 \\ub290\\ub07c\\uc2ed\\ub2c8\\uae4c?\", \"type\": \"scale_5\", \"options\": [\"\\ub9e4\\uc6b0 \\ubd88\\ub9cc\\uc871\", \"\\ubd88\\ub9cc\\uc871\", \"\\ubcf4\\ud1b5\", \"\\ub9cc\\uc871\", \"\\ub9e4\\uc6b0 \\ub9cc\\uc871\"], \"subQuestions\": []}, {\"id\": \"Q1-3\", \"category\": \"\\uc601\\uc5ed \\ud3c9\\uac00\", \"text\": \"[\\uad50\\ud1b5] **\\uad50\\ud1b5(\\uc8fc\\ucc28, \\ub300\\uc911\\uad50\\ud1b5 \\uc774\\uc6a9 \\ub4f1)**\\uc740 \\uc5bc\\ub9c8\\ub098 \\ub354 \\uac1c\\uc120\\ub420 \\ud544\\uc694\\uac00 \\uc788\\ub2e4\\u