INSERT INTO `reports` VALUES (1,NULL,'동래구 우리디자이너','주거','거리','전기자전거 재고 불균형 해결 제안','인도에 방치된 전기자전거로 인해 보행이 너무 불편합니다. 전용 주차구역 확보가 절실해요.','동래구','동래구 수안동','대호아파트 정문 앞',35.19830000,129.08310000,'/assets/archieve1.png','검토중',2,344,1,0,NULL,NULL,'null','2026-03-13 00:00:00'),(5,NULL,'동래구 우리디자이너','환경','골목쓰레기통','수안동 골목길 쓰레기 무단투기 해결 완료','골목길에 쓰레기가 너무 많았는데, 이번에 구청에서 수거함 설치와 CCTV 단속을 강화해주셨습니다. 정말 깨끗해졌어요!','동래구','동래구 수안동','대호아파트 후문 삼거리',35.19500000,129.08500000,'/assets/archieve1.png','개선중',2,539,1,1,NULL,NULL,'{\"title\": \"\\uace8\\ubaa9\\uae38 \\ud658\\uacbd \\uc815\\ube44 \\uacb0\\uacfc \\ubcf4\\uace0\", \"image\": \"/assets/archieve1.png\", \"content\": \"\\ubbfc\\uc6d0\\uc774 \\uc811\\uc218\\ub41c \\uc218\\uc548\\ub3d9 123-4\\ubc88\\uc9c0 \\uc77c\\ub300\\uc5d0 \\uc774\\ub3d9\\uc2dd CCTV 1\\ub300\\ub97c \\ucd94\\uac00 \\uc124\\uce58\\ud558\\uc600\\uc73c\\uba70, \\uc9c0\\uc5ed \\uc8fc\\ubbfc\\ub4e4\\uc758 \\uc758\\uacac\\uc744 \\uc218\\ub834\\ud558\\uc5ec \\ub300\\ud615 \\uc4f0\\ub808\\uae30 \\uc218\\uac70\\ud568 2\\uac1c\\ub97c \\ubc30\\uce58 \\uc644\\ub8cc\\ud558\\uc600\\uc2b5\\ub2c8\\ub2e4. \\uc55e\\uc73c\\ub85c\\ub3c4 \\uae68\\ub057\\ud55c \\ub3d9\\ub798\\uad6c\\ub97c \\uc704\\ud574 \\ub178\\ub825\\ud558\\uaca0\\uc2b5\\ub2c8\\ub2e4.\", \"manager\": \"\\ub3d9\\ub798\\uad6c\\uccad \\uc790\\uc6d0\\uc21c\\ud658\\uacfc\", \"result_date\": \"2026.04.05\"}','2026-04-01 00:00:00'),(101,NULL,'동래구 우리디자이너','산업·일자리','골목쓰레기통','공원 쓰레기통이 안전조치가 필요해요',NULL,'동래구','동래구 수안동',NULL,35.19830000,129.08310000,'/assets/archieve1.png','개선중',2,333,0,2,NULL,NULL,'null','2026-03-13 00:00:00'),(103,NULL,'수영구 학부모','교육','도로/교통 시설','학교 앞 횡단보도 신호등 고장',NULL,'수영구','수영구 광안동',NULL,35.20480000,129.07860000,'/assets/diagnosis_street.png','개선완료',4,1214,0,1,NULL,NULL,'{\"title\": \"\\uac1c\\uc120 \\uacb0\\uacfc\\ubcf4\\uae30\", \"image\": \"/assets/archieve3.png\", \"content\": \"U+one \\ub9c8\\ucf00\\ud130\\ub85c\\uc11c \\uadf8\\ub0e5 \\uc9c0\\ub098\\uce60 \\uc218\\uac00 \\uc5c6\\ub124\\uc694..(TT) \\uc804 \\uad6d